593→        // RemoteFetcher's cache is a simple file-based cache without
594→        // integrity checks. The caller (ExtendsResolver) handles
595→        // YAML parse errors.
596→        let content = fetcher.fetch(&url).unwrap();
597→        assert_eq!(content, "garbage\x00\x01\x02not yaml");
598→        // Still only 1 server hit (cache was returned, even if corrupted)
599→        mock.assert_calls(1);
