  1→//! User-defined variable evaluation.
  2→//!
  3→//! Evaluates `vars:` definitions from config into resolved string values
  4→//! that can be injected into [`InterpolationContext`](super::InterpolationContext).
  5→
  6→use crate::config::schema::VarDefinition;
  7→use crate::error::{BivvyError, Result};
  8→use crate::shell::execute_quiet;
  9→use std::collections::HashMap;
 10→use std::path::Path;
 11→
 12→/// Evaluate all variable definitions into resolved string values.
 13→///
 14→/// Static vars pass through unchanged. Computed vars run the command via
 15→/// `shell::execute_quiet` and use trimmed stdout. Fails if any computed
 16→/// var's command returns non-zero.
 17→pub fn evaluate_vars(
 18→    vars: &HashMap<String, VarDefinition>,
 19→    project_root: &Path,
 20→) -> Result<HashMap<String, String>> {
 21→    let mut resolved = HashMap::new();
 22→
 23→    for (name, def) in vars {
 24→        let value = match def {
 25→            VarDefinition::Static(s) => s.clone(),
 26→            VarDefinition::Computed { command } => {
 27→                let result = execute_quiet(command, Some(project_root))?;
 28→                if !result.success {
 29→                    return Err(BivvyError::ConfigValidationError {
 30→                        message: format!(
 31→                            "Variable '{}' command failed (exit {:?}): {}",
 32→                            name,
 33→                            result.exit_code,
 34→                            result.stderr.trim()
 35→                        ),
 36→                    });
 37→                }
 38→                result.stdout.trim().to_string()
 39→            }
 40→        };
 41→        resolved.insert(name.clone(), value);
 42→    }
 43→
 44→    Ok(resolved)
 45→}
