  1→//! Environment variable layering.
  2→//!
  3→//! This module provides priority-based environment variable management
  4→//! with source tracking for debugging.
  5→
  6→use std::collections::HashMap;
  7→
  8→/// Represents a layer of environment variables.
  9→///
 10→/// # Example
 11→///
 12→/// ```
 13→/// use bivvy::config::EnvLayer;
 14→///
 15→/// let mut layer = EnvLayer::new("config.yml");
 16→/// layer.set("DATABASE_URL", "postgres://localhost/db");
 17→/// layer.set("DEBUG", "true");
 18→///
 19→/// assert_eq!(layer.vars.get("DATABASE_URL").map(String::as_str), Some("postgres://localhost/db"));
 20→/// assert_eq!(layer.source, "config.yml");
 21→/// ```
 22→#[derive(Debug, Clone, Default)]
 23→pub struct EnvLayer {
 24→    /// Variables in this layer.
 25→    pub vars: HashMap<String, String>,
 26→    /// Source of this layer (for debugging).
 27→    pub source: String,
 28→}
 29→
 30→impl EnvLayer {
 31→    /// Create a new layer with the given source name.
 32→    pub fn new(source: impl Into<String>) -> Self {
 33→        Self {
 34→            vars: HashMap::new(),
 35→            source: source.into(),
 36→        }
 37→    }
 38→
 39→    /// Add a variable to this layer.
 40→    pub fn set(&mut self, key: impl Into<String>, value: impl Into<String>) {
 41→        self.vars.insert(key.into(), value.into());
 42→    }
 43→
 44→    /// Check if this layer has a variable.
 45→    pub fn contains(&self, key: &str) -> bool {
 46→        self.vars.contains_key(key)
 47→    }
 48→
 49→    /// Get the number of variables in this layer.
 50→    pub fn len(&self) -> usize {
 51→        self.vars.len()
 52→    }
 53→
 54→    /// Check if this layer is empty.
 55→    pub fn is_empty(&self) -> bool {
 56→        self.vars.is_empty()
 57→    }
 58→}
 59→
 60→/// Manages layered environment variables.
 61→///
 62→/// Variables from higher layers override variables from lower layers.
 63→/// The first layer pushed has lowest priority, the last has highest.
 64→///
 65→/// # Example
 66→///
 67→/// ```
 68→/// use bivvy::config::{EnvLayer, EnvLayerStack};
 69→///
 70→/// let mut stack = EnvLayerStack::new();
 71→///
 72→/// // Base layer (lowest priority)
 73→/// let mut base = EnvLayer::new("base");
 74→/// base.set("KEY", "base_value");
 75→/// base.set("BASE_ONLY", "from_base");
 76→/// stack.push(base);
 77→///
 78→/// // Override layer (higher priority)
 79→/// let mut overlay = EnvLayer::new("overlay");
 80→/// overlay.set("KEY", "override_value");
 81→/// stack.push(overlay);
 82→///
 83→/// assert_eq!(stack.get("KEY"), Some("override_value"));
 84→/// assert_eq!(stack.get("BASE_ONLY"), Some("from_base"));
 85→/// assert_eq!(stack.source_of("KEY"), Some("overlay"));
 86→/// ```
 87→pub struct EnvLayerStack {
 88→    /// Layers from lowest to highest priority.
 89→    layers: Vec<EnvLayer>,
 90→}
 91→
 92→impl EnvLayerStack {
 93→    /// Create a new empty stack.
 94→    pub fn new() -> Self {
 95→        Self { layers: vec![] }
 96→    }
 97→
 98→    /// Add a layer with the given priority.
 99→    ///
100→    /// Later layers have higher priority.
101→    pub fn push(&mut self, layer: EnvLayer) {
102→        self.layers.push(layer);
103→    }
104→
105→    /// Get the resolved value for a variable.
106→    ///
107→    /// Returns the value from the highest priority layer that contains the key.
108→    pub fn get(&self, key: &str) -> Option<&str> {
109→        // Higher index = higher priority
110→        for layer in self.layers.iter().rev() {
111→            if let Some(value) = layer.vars.get(key) {
112→                return Some(value);
113→            }
114→        }
115→        None
116→    }
117→
118→    /// Get all resolved variables.
119→    ///
120→    /// Higher priority layers override lower priority layers.
121→    pub fn resolve(&self) -> HashMap<String, String> {
122→        let mut result = HashMap::new();
123→        for layer in &self.layers {
124→            result.extend(layer.vars.clone());
125→        }
126→        result
127→    }
128→
129→    /// Get the source of a variable's value.
130→    ///
131→    /// Returns the source of the highest priority layer that contains the key.
132→    pub fn source_of(&self, key: &str) -> Option<&str> {
133→        for layer in self.layers.iter().rev() {
134→            if layer.vars.contains_key(key) {
135→                return Some(&layer.source);
136→            }
137→        }
138→        None
139→    }
140→
141→    /// Get all layers for inspection.
142→    pub fn layers(&self) -> &[EnvLayer] {
143→        &self.layers
144→    }
145→
146→    /// Get the number of layers.
147→    pub fn layer_count(&self) -> usize {
148→        self.layers.len()
149→    }
150→}
151→
152→impl Default for EnvLayerStack {
153→    fn default() -> Self {
154→        Self::new()
155→    }
156→}
