 17→#[test]
 18→fn full_config_workflow() {
 19→    let temp = TempDir::new().unwrap();
 20→    let bivvy_dir = temp.path().join(".bivvy");
 21→    fs::create_dir_all(&bivvy_dir).unwrap();
 22→
 23→    fs::write(
 24→        bivvy_dir.join("config.yml"),
 25→        r#"
 26→app_name: TestApp
 27→steps:
 28→  test:
 29→    command: "echo ${message}"
 30→workflows:
 31→  default:
 32→    steps: [test]
 33→"#,
 34→    )
 35→    .unwrap();
 36→
 37→    let config = load_merged_config(temp.path()).unwrap();
 38→    validate(&config).unwrap();
 39→
 40→    let mut ctx = InterpolationContext::new();
 41→    ctx.prompts
 42→        .insert("message".to_string(), "hello".to_string());
