impl ConfigPaths {
    /// Find a config file, trying .yml first, then .toml.
    /// Returns an error if both exist (ambiguous).
    fn find_config_file(dir: &Path, base_name: &str) -> std::result::Result<Option<PathBuf>, String> {
        let yml_path = dir.join(format!("{}.yml", base_name));
        let toml_path = dir.join(format!("{}.toml", base_name));
        let yml_exists = yml_path.exists();
        let toml_exists = toml_path.exists();

        match (yml_exists, toml_exists) {
            (true, true) => Err(format!(
                "Both {}.yml and {}.toml exist in {}. Remove one to resolve ambiguity.",
                base_name, base_name, dir.display()
            )),
            (true, false) => Ok(Some(yml_path)),
            (false, true) => Ok(Some(toml_path)),
            (false, false) => Ok(None),
        }
    }
}
