impl ConfigPaths {
    /// Check that no location has both .yml and .toml config files.
    fn validate_no_format_conflicts(project_root: &Path) -> Result<()> {
        let bivvy_dir = project_root.join(".bivvy");

        // Check project config
        let yml = bivvy_dir.join("config.yml");
        let toml = bivvy_dir.join("config.toml");
        if yml.exists() && toml.exists() {
            return Err(BivvyError::ConfigParseError {
                path: bivvy_dir.clone(),
                message: "Both config.yml and config.toml exist. Remove one to resolve ambiguity.".to_string(),
            });
        }

        // Check local config
        let yml_local = bivvy_dir.join("config.local.yml");
        let toml_local = bivvy_dir.join("config.local.toml");
        if yml_local.exists() && toml_local.exists() {
            return Err(BivvyError::ConfigParseError {
                path: bivvy_dir,
                message: "Both config.local.yml and config.local.toml exist. Remove one to resolve ambiguity.".to_string(),
            });
        }

        Ok(())
    }
}
